import{useEffect,useState}from"react";import{createUserWithEmailAndPassword,deleteUser,signInWithEmailAndPassword,sendPasswordResetEmail,onAuthStateChanged,signOut}from"firebase/auth";import type{User}from"firebase/auth";import{auth}from"./firebase";import{api,apiFile}from"./api";import{Pickaxe,Wallet,LogOut,RefreshCw,ShieldCheck,Copy,Download}from"lucide-react";
type Profile={email:string;display_name:string;referral_code:string;referred_by_user_id:string|null;activated:number;activated_at:string|null;last_hash_at:string|null;mining_balance_sats:number;session_active:number;session_started_at:string|null;session_credited_sats:number;session_ends_at:string|null;qualified_referrals:number;total_referrals:number;pending_referrals:number};const ADMIN="johnmutahi44@gmail.com";
const REFERRAL_STORAGE_KEY="mutah_hash_referral_code";
function captureReferralCode():string|null{
 if(typeof window==="undefined")return null;
 const incoming=new URLSearchParams(window.location.search).get("ref");
 const normalized=incoming===null?null:incoming.trim().toUpperCase();
 const valid=!!normalized&&/^[A-F0-9]{10}$/.test(normalized);
 if(incoming!==null){
  try{if(valid)localStorage.setItem(REFERRAL_STORAGE_KEY,normalized!);else localStorage.removeItem(REFERRAL_STORAGE_KEY);}catch{/* Continue with session storage or the URL value. */}
  try{if(valid)sessionStorage.setItem(REFERRAL_STORAGE_KEY,normalized!);else sessionStorage.removeItem(REFERRAL_STORAGE_KEY);}catch{/* Storage can be disabled by the browser. */}
 }
 try{const saved=localStorage.getItem(REFERRAL_STORAGE_KEY);if(saved&&/^[A-F0-9]{10}$/.test(saved))return saved;}catch{/* Try session storage below. */}
 try{const saved=sessionStorage.getItem(REFERRAL_STORAGE_KEY);if(saved&&/^[A-F0-9]{10}$/.test(saved))return saved;}catch{/* Storage can be disabled. */}
 return valid?normalized:null;
}
function clearReferralCode(){try{localStorage.removeItem(REFERRAL_STORAGE_KEY);}catch{/* Ignore unavailable local storage. */}try{sessionStorage.removeItem(REFERRAL_STORAGE_KEY);}catch{/* Ignore unavailable session storage. */}}
if(typeof window!=="undefined"){try{captureReferralCode();}catch{/* Referral capture must never prevent the app from loading. */}}
function normalizeKenyanPhone(value:string){let digits=value.replace(/\D/g,"");if(digits.length===10&&digits.startsWith("0"))digits="254"+digits.slice(1);if(digits.length===9&&(digits.startsWith("7")||digits.startsWith("1")))digits="254"+digits;return digits;}

